// ByteEncode_12 of canonical coefficients.
// func kemEncode12AVX2(out *[384]byte, f *kemPoly)
TEXT ·kemEncode12AVX2(SB), NOSPLIT, $0-16
	MOVQ	out+0(FP), DI
	MOVQ	f+8(FP), SI
	LEAQ	kemX86<>(SB), R13
	VMOVDQU	2656(R13), Y15
	VMOVDQU	2688(R13), Y14
	VMOVDQU	2720(R13), Y13
	MOVQ	$16, CX
loop:
	VMOVDQU	(SI), Y0
	VPMADDWD	Y15, Y0, Y0
	VPSHUFB	Y14, Y0, Y0
	VPERMD	Y0, Y13, Y0
	VMOVDQU	X0, (DI)
	VEXTRACTI128	$1, Y0, X1
	VMOVQ	X1, 16(DI)
	ADDQ	$32, SI
	ADDQ	$24, DI
	DECQ	CX
	JNZ	loop
	VZEROUPPER
	RET

